import { parse, format, resolve } from "node:url";

export function parseLink(href, parseQuery) {
  return parse(href, parseQuery);
}

export function canonical(href) {
  return format(href);
}

export function joinLink(base, reference) {
  return resolve(base, reference);
}

export function describe(href) {
  const u = parse(href, true);
  return `${u.protocol} ${u.host} ${u.pathname} ${JSON.stringify(u.query)}`;
}
